UPDATE TB_EEP_EMPLY_M
SET EMPLY_ID = #{EMPLY_ID}, EMPLY_NM = #{EMPLY_NM}, EMPLY_EMAIL = #{EMPLY_EMAIL,jdbcType=VARCHAR}, EMPLY_PH_NUM = #{EMPLY_PH_NUM,jdbcType=VARCHAR}
	, EMPLY_HOME_ADDR = #{EMPLY_HOME_ADDR,jdbcType=VARCHAR}, EMPLY_SEX_TYP_CD = #{EMPLY_SEX_TYP_CD,jdbcType=VARCHAR}
	, EMPLY_RRN = #{EMPLY_RRN}
	, EMPLY_UPDT_DT = NOW()
WHERE EMPLY_SQ = #{EMPLY_SQ}

UPDATE TB_EEP_EMPLY_M
SET EMPLY_UPDT_DT = NOW()
	, USE_YN = #{USE_YN}
	, DEL_YN = #{DEL_YN}
WHERE EMPLY_SQ = #{EMPLY_SQ}
